quiz.question:
次の定義があるとき、`res.data.name` の型は何か。

```ts
interface ApiResponse<T> { status: number; data: T; }
interface User { id: number; name: string; }
const res: ApiResponse<User> = { status: 200, data: { id: 1, name: "佐藤" } };
```

次のコードの説明として正しいものはどれか。

```ts
async function getUser(): Promise<User> { /* ... */ }
const p = getUser();
console.log(p.name);
```

quiz.setup:
declare function require(name: string): any;
const input: string = require("fs").readFileSync(0, "utf8");

interface ApiResponse<T> {
  status: number;
  data: T;
}

// status と data を受け取り、ApiResponse<T> を作って返す
function wrap<T>(status: number, data: T): ApiResponse<T> {
  // ここを書き換える
  return { status: 0, data: data };
}

// 配列の先頭の要素を返す。空なら undefined
function first<T>(items: T[]): T | undefined {
  // ここを書き換える
  return undefined;
}

const words = input.trim() === "" ? [] : input.trim().split(",");
const r1 = wrap(words.length === 0 ? 204 : 200, words);
const f1 = first(r1.data);
console.log(r1.status + " " + (f1 === undefined ? "(なし)" : f1.toUpperCase()));

const lengths = words.map((w) => w.length);
const r2 = wrap(200, lengths);
const f2 = first(r2.data);
console.log(r2.status + " " + (f2 === undefined ? "(なし)" : f2.toFixed(1)));

quiz.answer:
declare function require(name: string): any;
const input: string = require("fs").readFileSync(0, "utf8");

interface ApiResponse<T> {
  status: number;
  data: T;
}

function wrap<T>(status: number, data: T): ApiResponse<T> {
  return { status: status, data: data };
}

function first<T>(items: T[]): T | undefined {
  return items[0];
}

const words = input.trim() === "" ? [] : input.trim().split(",");
const r1 = wrap(words.length === 0 ? 204 : 200, words);
const f1 = first(r1.data);
console.log(r1.status + " " + (f1 === undefined ? "(なし)" : f1.toUpperCase()));

const lengths = words.map((w) => w.length);
const r2 = wrap(200, lengths);
const f2 = first(r2.data);
console.log(r2.status + " " + (f2 === undefined ? "(なし)" : f2.toFixed(1)));
